3. import org.slf4j.MDC;
4. import org.springframework.http.HttpRequest;
5. import org.springframework.http.client.ClientHttpRequestExecution;
6. import org.springframework.http.client.ClientHttpRequestInterceptor;
7. import org.springframework.http.client.ClientHttpResponse;
8. 
9. import java.io.IOException;
10. 
11. public class RestTemplateSetHeaderInterceptor implements ClientHttpRequestInterceptor {
12.     
13.     public ClientHttpResponse intercept(HttpRequest request, byte[] body, ClientHttpRequestExecution execution) throws IOException {
14.         request.getHeaders().add("X-Correlation-ID", MDC.get("X-Correlation-ID"));
15.         request.getHeaders().add("X-Request-ID", MDC.get("X-Request-ID"));
16.         return execution.execute(request, body);
17.     }
18. 
19. }
